cd /tmp/sv-6bbe9d3c25a74feb9d749bf5caa78618/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: project_name -> framework -> package -> version
def build_lookup(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        result[name] = {}
        for fw in proj['frameworks']:
            result[name][fw['framework']] = {p['id']: p['resolvedVersion'] for p in fw['topLevelPackages']}
    return result

b = build_lookup(baseline)
a = build_lookup(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bp = b.get(proj,{}).get(fw,{})
        ap = a.get(proj,{}).get(fw,{})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg, 'N/A')
            av = ap.get(pkg, 'N/A')
            label = f'{proj} ({fw})'
            if bv != av:
                changes.append((label, pkg, bv, av))
            else:
                unchanged.append((label, pkg, av))

if changes:
    print('CHANGES:')
    print(f'{\"Project\":<25} {\"Package\":<45} {\"Before\":<12} {\"After\":<12}')
    for c in changes:
        print(f'{c[0]:<25} {c[1]:<45} {c[2]:<12} {c[3]:<12}')
else:
    print('No version changes detected.')

print()
print(f'UNCHANGED: {len(unchanged)} package-project combinations resolve identically.')
"

